package com.jnapanam.sportszone.notification.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="notification_preferences")public class NotificationPreference{@Id@Column(name="user_id")private UUID userId;@Column(name="email_enabled",nullable=false)private boolean emailEnabled;@Column(name="sms_enabled",nullable=false)private boolean smsEnabled;@Column(name="push_enabled",nullable=false)private boolean pushEnabled;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected NotificationPreference(){}public NotificationPreference(User u){userId=u.getId();emailEnabled=smsEnabled=pushEnabled=true;updatedAt=Instant.now();}public void update(boolean e,boolean s,boolean p){emailEnabled=e;smsEnabled=s;pushEnabled=p;updatedAt=Instant.now();}public boolean isEmailEnabled(){return emailEnabled;}public boolean isSmsEnabled(){return smsEnabled;}public boolean isPushEnabled(){return pushEnabled;}public UUID getUserId(){return userId;}}
